<?php $page_title='Volunteers'; require_once 'includes/header.php'; require_login(); $vols=$pdo->query("SELECT v.*,u.name,u.city,u.avatar FROM volunteers v JOIN users u ON u.id=v.user_id WHERE v.verified=1 ORDER BY v.availability='available' DESC,v.hours DESC")->fetchAll(); ?>
<section class="page-hero"><span class="kicker">VOLUNTEER NETWORK</span><h1>People who move food forward.</h1><p>Find verified volunteers and discover how the community supports pickups and deliveries.</p><a class="btn primary" href="profile.php">Become a volunteer →</a></section><div class="people-grid-v2 public-people"><?php foreach($vols as $v):?><article class="person-card-v2"><span class="avatar-md"><?php if($v['avatar']):?><img src="<?=e($v['avatar'])?>"><?php else:?><?=e(strtoupper(substr($v['name'],0,1)))?><?php endif;?></span><b><?=e($v['name'])?> ✓</b><small><?=e($v['service_area']?:$v['city']?:'Local volunteer')?></small><span class="role-chip"><?=e($v['availability'])?></span><p class="muted"><?=e($v['skills']?:'Food pickup & community support')?></p><small><?=e($v['hours'])?> volunteer hours</small></article><?php endforeach;if(!$vols):?><div class="empty-state full">No verified volunteers yet. Admins can add volunteers from the admin panel.</div><?php endif;?></div>
<?php require_once 'includes/footer.php'; ?>
